import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o}from"./chunks/OFF.BrU7kQE-.js";import{_ as t}from"./chunks/EN.P9aPnFBv.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as a,o as n,c as r,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const b=JSON.parse('{"title":"Prononcer les valeurs","description":"","frontmatter":{"source_hash":null,"source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/speak.md","filePath":"fr/use/speak.md"}'),p={name:"fr/use/speak.md"};function d(c,s,m,u,v,_){return n(),r("div",null,[...s[0]||(s[0]=[l('<div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_speak_reading_grey600_48dp.png" style="width:5%;"> Prononcer les valeurs</p></div><p>Si votre téléphone prend en charge la synthèse vocale, xDrip peut vous annoncer oralement divers événements.</p><div class="admonition xdripitem"><p class="admonition-title">Prononcer les valeurs <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Si le téléphone a des capacités text-to-speech, il prononcera chaque nouvelle lecture.</p></div><p>Lorsque vous activez cette fonction, si la synthèse vocale n&#39;est pas déjà présente sur votre appareil, vous devrez l&#39;installer depuis le <a href="https://play.google.com/store/apps/details?id=com.google.android.tts" target="_blank" rel="noreferrer">Google Play Store</a> ou la boutique d&#39;applications du fabricant de votre téléphone.</p><div class="admonition xdripitem"><p class="admonition-title">Installer les données Text-To-Speech?</p><p>Installer les données Text-To-Speech?<br> (Après l&#39;installation des langues, vous devrez peut-être appuyer sur &quot;Redémarrer le collecteur&quot; dans État du système.)<br> Non    OK</p></div><p>Vous pouvez choisir d&#39;entendre votre glycémie dans certaines conditions (variation supérieure à un certain seuil) ou à intervalles réguliers.</p><div class="admonition xdripitem"><p class="admonition-title">Lors de changements par (0 mgdl ou mmol/l)</p></div><div class="admonition xdripitem"><p class="admonition-title">Ou par nombre de minutes (0)</p></div><p>Les alertes peuvent aussi être prononcées si vous activez cette option.</p><div class="admonition xdripitem"><p class="admonition-title">Prononcer les alertes <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Donner également des messages d&#39;alerte prononcées</p></div><p>Vous pouvez faire prononcer la tendance, et faire répéter deux fois les valeurs ou toutes les informations prononcées.</p><div class="admonition xdripitem"><p class="admonition-title">Prononcer le nom de la flèche de tendance <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Prononcer la valeur de glycémie deux fois <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Prononcer tout deux fois <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>Si vous voulez imposer une autre langue pour les annonces, vous pouvez la choisir en saisissant manuellement le code <a href="https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes" target="_blank" rel="noreferrer">ISO639-1</a> de la langue (par exemple <code>de</code>), suivi éventuellement d&#39;un tiret bas (<code>_</code>) et d&#39;un code régional défini par <a href="https://en.wikipedia.org/wiki/ISO_3166-1_alpha-2#Officially_assigned_code_elements" target="_blank" rel="noreferrer">ISO3166-1 alpha 2</a> (par exemple <code>en_IN</code>).</p><div class="admonition xdripitem"><p class="admonition-title">Paramètres régionaux utilisés pour les lectures énoncées, par exemple : fr ou en_IN</p></div><p>Vous pouvez modifier le ton de la voix et la vitesse de lecture.</p><div class="admonition xdripitem"><p class="admonition-title">Vitesse de prononciation</p></div><div class="admonition xdripitem"><p class="admonition-title">Ton de la voix</p></div><p>Et, si vous le souhaitez, ajouter un raccourci dans le menu principal.</p><div class="admonition xdripitem"><p class="admonition-title">Raccourci pour les lectures prononcées <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Afficher un raccourci dans le menu ☰ pour gérer les prononciations de lectures</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',23)])])}const z=a(p,[["render",d]]);export{b as __pageData,z as default};
